"""es — faith_b."""

T = {
"faith_071": ("¿Qué significa el nombre de Allah «As-Salam»?", ["La Paz, libre de todo defecto", "El Creador", "El Proveedor", "El Poderoso"], "As-Salam figura entre los nombres enumerados al final de la sura Al-Hashr: Él es la Paz, libre de toda imperfección."),
"faith_072": ("¿Qué atributos pone la aleya 59:22 junto al nombre de Allah, tras «no hay más dios que Él»?", ["Conocedor de lo oculto y lo manifiesto, el Compasivo", "El Rey y el Guerrero", "El Rico y el Generoso", "El Fuerte y el Veloz"], "«Él es Allah, no hay más dios que Él, Conocedor de lo oculto y lo manifiesto. Él es el Compasivo, el Misericordioso»."),
"faith_073": ("¿Qué ordena el Corán hacer con los más bellos nombres de Allah?", ["Invocarle por ellos", "Solo contarlos", "Escribirlos en las puertas", "Callarlos"], "«A Allah pertenecen los nombres más bellos: invocadle, pues, por ellos»."),
"faith_074": ("¿Cómo presenta la sura Ta-Ha los nombres de Allah?", ["«¡Allah! No hay más dios que Él. Suyos son los nombres más bellos»", "«Sus nombres están ocultos»", "«Sus nombres son incontables»", "«Sus nombres son nueve»"], "«¡Allah! No hay más dios que Él. Suyos son los nombres más bellos»."),
"faith_075": ("¿Qué fórmula emplea el Corán para descartar toda semejanza con Allah?", ["«No hay nada semejante a Él; y Él es el que todo lo oye, el que todo lo ve»", "«Es el mayor de los reyes»", "«Es como la luz»", "«Nadie Le ve»"], "«No hay nada semejante a Él; y Él es el que todo lo oye, el que todo lo ve»."),
"faith_076": ("¿Qué dice la Aleya del Trono sobre la somnolencia y el sueño?", ["Ni la somnolencia ni el sueño Le afectan", "Duerme de noche", "Descansa el séptimo día", "Vela un día sí y otro no"], "«No Le afecta la somnolencia ni el sueño»."),
"faith_077": ("¿Qué dice el Corán del conocimiento de Allah sobre la hoja que cae?", ["No cae una hoja sin que Él lo sepa", "Lo sabe después", "Se lo dicen los ángeles", "No está escrito"], "«Él tiene las llaves de lo oculto… no cae una hoja sin que Él lo sepa»."),
"faith_078": ("¿Que qué está Allah más cerca del ser humano, según la sura Qaf?", ["De su vena yugular", "De su sombra", "De su voz", "De su casa"], "«Hemos creado al hombre y sabemos lo que su alma le susurra; estamos más cerca de él que su vena yugular»."),
"faith_079": ("¿Cómo describe el Corán a los ángeles encargados del Fuego?", ["No desobedecen a Allah y hacen lo que se les ordena", "Algunos vacilan", "Duermen", "Eligen"], "«…ángeles duros y severos, que no desobedecen a Allah en lo que les ordena y hacen lo que se les manda»."),
"faith_080": ("¿Cómo describe el Corán a los ángeles respecto de la palabra de Allah?", ["No se Le adelantan en el hablar y obran según Su orden", "Discuten Sus órdenes", "Deciden por sí solos", "Callan siempre"], "«Son más bien siervos honrados: no se Le adelantan en el hablar y obran según Su orden»."),
"faith_081": ("¿Qué ángel nombra el Corán como aquel que hizo descender la revelación al corazón del Profeta ﷺ?", ["Yibril (Gabriel)", "Mika'il (Miguel)", "Israfil", "Malik"], "«Di: quien sea enemigo de Yibril… él es quien lo ha hecho descender sobre tu corazón con permiso de Allah»."),
"faith_082": ("¿Qué otro ángel se nombra junto a Yibril en la sura Al-Baqara?", ["Mikal (Miguel)", "Israfil", "Ridwan", "Munkar"], "«Quien sea enemigo de Allah, de Sus ángeles, de Sus mensajeros, de Yibril y de Mikal…»"),
"faith_083": ("¿Qué objetos de fe enumera la aleya 4:136?", ["Allah, Su Mensajero, el Libro revelado y los Libros anteriores", "Solo el Libro", "Solo los profetas", "Solo los ángeles"], "«¡Creyentes! Creed en Allah, en Su mensajero, en el Libro que ha hecho descender sobre Su mensajero y en el Libro que hizo descender antes»."),
"faith_084": ("¿Qué Libro menciona el Corán como dado a Dawud?", ["El Zabur (los Salmos)", "La Torá", "El Evangelio", "Las Escrituras de Ibrahim"], "«…y dimos a Dawud el Zabur»."),
"faith_085": ("¿Qué sura lleva el nombre de los genios, que escucharon el Corán y creyeron?", ["Al-Yinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Di: se me ha revelado que un grupo de genios escuchó y dijo: hemos oído una recitación maravillosa»."),
"faith_086": ("¿Para qué fueron creados los genios y los hombres, según la sura Az-Zariyat?", ["Para que Le adoren", "Para poblar la tierra", "Para construir", "Para disputar"], "«No he creado a los genios y a los hombres sino para que Me adoren»."),
"faith_087": ("¿Qué dice el Corán acerca de toda alma y la muerte?", ["Toda alma probará la muerte", "Algunas almas no mueren", "La muerte es una duda", "La muerte es un sueño sin fin"], "«Toda alma probará la muerte, y solo el Día de la Resurrección recibiréis vuestra recompensa completa»."),
"faith_088": ("¿En qué estado saldrán los hombres, según la sura Az-Zalzala, para que se les muestren sus obras?", ["En grupos separados", "Todos juntos en una sola fila", "Dormidos", "Silenciosos e invisibles"], "«Ese día los hombres saldrán en grupos separados para que se les muestren sus obras»."),
"faith_089": ("¿Cómo describe la sura Al-Kahf el registro de las obras en el Último Día?", ["No deja nada, pequeño ni grande, sin consignarlo", "Solo registra lo grande", "Se borra", "Lo escriben los hombres"], "«Dirán: “¡Ay de nosotros! ¿Qué libro es este, que no deja nada, pequeño ni grande, sin consignarlo?”»"),
"faith_090": ("¿Qué dice el Corán de los miembros del cuerpo el Día del Juicio?", ["Las manos hablarán y los pies darán testimonio", "Permanecerán mudos", "Estarán ocultos", "Serán transformados"], "«Ese día sellaremos sus bocas, y Nos hablarán sus manos y darán testimonio sus pies de lo que hacían»."),
"faith_091": ("¿Cómo califica el Corán la oración en cuanto a su horario?", ["Una prescripción a horas fijadas", "Libre a cualquier hora", "Una vez por semana", "Solo de noche"], "«Ciertamente, la oración es para los creyentes una prescripción en tiempos determinados»."),
"faith_092": ("¿De qué preserva la oración, según la sura Al-'Ankabut?", ["De la indecencia y lo reprobable", "Del hambre", "De la enfermedad", "Del viaje"], "«Y establece la oración: la oración preserva de la indecencia y de lo reprobable»."),
"faith_093": ("¿Qué oración señala el Corán en particular como «la oración intermedia»?", ["Se la nombra sin identificarla, en la orden de guardar las oraciones", "Solo la del alba", "Solo la del ocaso", "La del viernes"], "«Guardad las oraciones y la oración intermedia, y presentaos ante Allah con humildad»."),
"faith_094": ("¿Con qué fin ordena el Corán la oración, en la sura Ta-Ha?", ["Para el recuerdo de Allah", "Para descansar", "Para reunirse", "Para contar las horas"], "«Yo soy Allah: no hay más dios que Yo. Adórame, pues, y establece la oración para Mi recuerdo»."),
"faith_095": ("¿Qué cualidad de la oración abre la lista de los creyentes que triunfan, en Al-Mu'minun?", ["La humildad (jushu') en la oración", "La longitud", "La rapidez", "El número"], "«Han triunfado los creyentes: aquellos que en su oración son humildes»."),
"faith_096": ("¿Qué oración describe la sura Al-Isra como «atestiguada» (mashhuda)?", ["La recitación del alba", "La oración del ocaso", "La del mediodía", "La del viernes"], "«Establece la oración desde que declina el sol hasta la oscuridad de la noche, y la recitación del alba: la recitación del alba es atestiguada»."),
"faith_097": ("¿Con qué dos cosas ordena el Corán buscar auxilio?", ["Con la paciencia y la oración", "Con la fuerza y la riqueza", "Con el viaje y el descanso", "Con el silencio y la soledad"], "«¡Creyentes! Buscad auxilio en la paciencia y la oración: Allah está con los pacientes»."),
"faith_098": ("¿Cuántas rak'as tiene la oración obligatoria del Duhr?", ["Cuatro", "Dos", "Tres", "Cinco"], "El Duhr, el 'Asr y el 'Isha tienen cada uno cuatro rak'as obligatorias; en esto coinciden las escuelas."),
"faith_099": ("¿Cuál es la última de las cinco oraciones obligatorias del día?", ["Al-'Isha", "Al-Fayr", "Al-Magrib", "Al-'Asr"], "El orden es: Fayr, Duhr, 'Asr, Magrib, 'Isha."),
"faith_100": ("¿Cómo se llama la postura de postración en la oración?", ["El suyud", "El ruku'", "El qiyam", "El tashahhud"], "El qiyam es estar de pie, el ruku' la inclinación, el suyud la postración y el tashahhud la sentada del testimonio."),
"faith_101": ("¿Qué prevé el Corán para el enfermo o el viajero durante Ramadán?", ["Un número igual de días para recuperar", "Nada en absoluto", "Una obligación doble", "Un ayuno perpetuo"], "«Quien de vosotros esté enfermo o de viaje, que ayune un número igual de otros días»."),
"faith_102": ("¿Qué finalidad da el Corán al ayuno prescrito?", ["Alcanzar la piedad (taqwa)", "Adelgazar", "Ahorrar", "Descansar"], "«Se os ha prescrito el ayuno como se prescribió a quienes os precedieron, para que alcancéis la piedad»."),
"faith_103": ("¿Qué responde Allah, en medio de las aleyas del ayuno, a quien pregunta por Su cercanía?", ["«Estoy cerca: respondo a la súplica de quien Me invoca»", "«Esperad la noche»", "«Preguntad a los ángeles»", "«Buscad lejos»"], "«Cuando Mis siervos te pregunten por Mí, ciertamente estoy cerca: respondo a la súplica del que Me invoca cuando Me invoca»."),
"faith_104": ("¿Cuántas categorías de beneficiarios del zakat enumera el Corán?", ["Ocho", "Tres", "Cinco", "Doce"], "«Las limosnas son solo para los pobres, los necesitados, quienes trabajan en ellas, aquellos cuyos corazones hay que ganar, la liberación de cautivos, los endeudados, la causa de Allah y el viajero»."),
"faith_105": ("¿Qué efecto atribuye el Corán al zakat tomado de los bienes?", ["Purifica y hace crecer", "Empobrece", "Es simbólico", "Sustituye a la oración"], "«Toma de sus bienes una limosna con la que los purifiques y los acrecientes»."),
"faith_106": ("¿Qué dos obligaciones asocia el Corán con más frecuencia?", ["La oración y el zakat", "El ayuno y el viaje", "La peregrinación y el comercio", "La lectura y la escritura"], "«Estableced la oración y dad el zakat; todo el bien que adelantéis para vosotros mismos lo hallaréis junto a Allah»."),
"faith_107": ("¿Qué dice el Corán que llega a Allah en el sacrificio?", ["Ni la carne ni la sangre, sino la piedad del creyente", "Solo la carne", "Solo la sangre", "El número de reses"], "«Ni su carne ni su sangre llegan a Allah, pero sí Le llega la piedad de vuestra parte»."),
"faith_108": ("¿Cuál es la mejor provisión para la peregrinación, según el Corán?", ["La piedad", "El oro", "Los víveres", "Las monturas"], "«Y tomad provisiones; pero la mejor provisión es la piedad»."),
"faith_109": ("¿Qué rito menciona el Corán alrededor de la Antigua Casa?", ["La circunvalación (tawaf)", "Correr por el desierto", "Subir una colina", "Ayunar allí"], "«…y que den las vueltas alrededor de la Antigua Casa»."),
"faith_110": ("¿Dónde ordena el Corán invocar a Allah, tras partir de 'Arafat?", ["Junto a al-Mash'ar al-Haram, en Muzdalifa", "En el monte Uhud", "En Quba", "En Taif"], "«Cuando partáis en masa de 'Arafat, recordad a Allah junto a al-Mash'ar al-Haram»."),
"faith_111": ("¿Qué clase de arrepentimiento pide el Corán a los creyentes?", ["Un arrepentimiento sincero (tawba nasuh)", "Un arrepentimiento escrito", "Un arrepentimiento público", "Un arrepentimiento anual"], "«¡Creyentes! Volveos a Allah con un arrepentimiento sincero»."),
"faith_112": ("¿Qué dice la sura Ash-Shura sobre la aceptación del arrepentimiento?", ["Él es quien acepta el arrepentimiento de Sus siervos y perdona las malas obras", "El arrepentimiento no se acepta", "Hace falta un intermediario", "Hay que esperar un año"], "«Él es quien acepta el arrepentimiento de Sus siervos, perdona las malas obras y sabe lo que hacéis»."),
"faith_113": ("¿Qué hacen aquellos a quienes elogia el Corán, tras cometer una falta?", ["Recuerdan a Allah y piden perdón", "Huyen", "Callan", "Culpan a otros"], "«Y aquellos que, cuando cometen una indecencia o se perjudican a sí mismos, recuerdan a Allah y piden perdón por sus pecados»."),
"faith_114": ("¿Con qué frecuencia ordena el Corán recordar a Allah, en la sura Al-Ahzab?", ["Mucho, mañana y tarde", "Una vez al año", "Una vez por semana", "Solo de viaje"], "«¡Creyentes! Recordad mucho a Allah, y glorificadle mañana y tarde»."),
"faith_115": ("¿Sobre qué meditan «los dotados de entendimiento», al final de la sura Al 'Imran?", ["Sobre la creación de los cielos y la tierra, en toda postura", "Sobre las cosechas", "Sobre las caravanas", "Sobre las genealogías"], "«Quienes recuerdan a Allah de pie, sentados y acostados, y meditan sobre la creación de los cielos y la tierra»."),
"faith_116": ("¿Qué ordena hacer el Corán una vez tomada una decisión?", ["Confiar en Allah", "Esperar una señal", "Preguntar a un adivino", "Renunciar"], "«Y cuando hayas decidido, confía en Allah: Allah ama a quienes confían en Él»."),
"faith_117": ("¿Hacia quién dirige la sura Ash-Sharh el anhelo, una vez concluida la tarea?", ["Hacia su Señor", "Hacia el descanso", "Hacia la familia", "Hacia la gente"], "«Cuando quedes libre, esfuérzate; y a tu Señor dirige tu anhelo»."),
"faith_118": ("¿Con qué compara la sura Al-Hadid la vida de este mundo?", ["Con una lluvia cuya vegetación admira, luego amarillea y se vuelve rastrojo", "Con un largo viaje", "Con una montaña", "Con un océano"], "«Sabed que la vida de este mundo no es sino juego y distracción… como una lluvia cuya vegetación admira a los labradores; luego se seca, la ves amarillear y se vuelve rastrojo»."),
"faith_119": ("¿Qué declara el Corán mejor que los bienes y los hijos, adorno de este mundo?", ["Las buenas obras que perduran", "El oro", "La fama", "Las tierras"], "«Los bienes y los hijos son el adorno de la vida de este mundo, pero las buenas obras que perduran son mejor recompensa ante tu Señor»."),
"faith_120": ("¿Qué pregunta plantea el Corán sobre el fin de la creación del hombre?", ["«¿Pensabais que os habíamos creado sin propósito?»", "«¿Quién os nombró?»", "«¿Adónde iréis?»", "«¿Cuántos sois?»"], "«¿Pensabais que os habíamos creado sin propósito y que no seríais devueltos a Nosotros?»"),
"faith_121": ("¿Qué promesa hace el Corán a quien recuerda a Allah?", ["«Recordadme y Yo os recordaré»", "«Seréis ricos»", "«Viviréis mucho»", "«Viajaréis»"], "«Recordadme, pues, y Yo os recordaré. Y sedme agradecidos y no Me neguéis»."),
"faith_122": ("¿A quién ordena el Corán remitir las disputas?", ["A Allah y al Mensajero ﷺ", "A los ancianos", "Al mercado", "A los poetas"], "«Y si disputáis sobre algo, remitidlo a Allah y al Mensajero, si creéis en Allah y en el Último Día»."),
"faith_123": ("¿Cómo describe la sura Al-Anfal los corazones de los creyentes al mencionarse a Allah?", ["Sus corazones se estremecen y su fe aumenta con la recitación", "Se endurecen", "Se adormecen", "Olvidan"], "«Los creyentes son solo aquellos cuyos corazones se estremecen cuando se menciona a Allah, y cuya fe aumenta cuando se les recitan Sus aleyas»."),
"faith_124": ("¿Qué ordena el Corán dedicar por entero al Señor de los mundos?", ["La oración, los actos de devoción, la vida y la muerte", "El comercio", "Las cosechas", "Los viajes"], "«Di: mi oración, mis actos de devoción, mi vida y mi muerte pertenecen a Allah, Señor de los mundos»."),
"faith_125": ("¿Qué condición pone la sura Al-Bayyina a la adoración ordenada?", ["Adorar a Allah con devoción sincera y exclusiva", "Adorar en público", "Adorar por escrito", "Adorar solo en grupo"], "«No se les ordenó sino adorar a Allah, con devoción sincera, establecer la oración y dar el zakat»."),
"faith_126": ("¿Qué describe el Corán como fluyendo en los jardines prometidos a los piadosos?", ["Ríos", "Caminos", "Puentes", "Pozos"], "El Corán describe repetidamente los jardines «bajo los cuales corren los ríos»."),
"faith_127": ("¿Qué dice el Corán de lo que se oculta a los creyentes como recompensa?", ["Nadie sabe qué alegría de los ojos les está reservada", "Todo está descrito en detalle", "Son riquezas", "Son reinos"], "«Nadie sabe qué alegría de los ojos les está reservada, como recompensa por lo que hacían»."),
"faith_128": ("¿Qué promete el Corán a quienes obran el bien, además de la mejor recompensa?", ["Un aumento (ziyada)", "Un aplazamiento", "Un reino", "Un libro"], "«Quienes obran el bien tendrán lo mejor y aún más»."),
"faith_129": ("¿Cómo describe el Corán la acogida de los piadosos a la entrada del Paraíso?", ["«¡La paz sea con vosotros! Habéis sido buenos: entrad para morar eternamente»", "En silencio", "Tras un largo juicio", "Uno a uno sin palabra"], "«Sus guardianes les dirán: “La paz sea con vosotros; habéis sido buenos: entrad para morar eternamente”»."),
"faith_130": ("¿Hacia qué ordena el Corán apresurarse, en la sura Al 'Imran?", ["Hacia un perdón de su Señor y un Paraíso tan ancho como los cielos y la tierra", "Hacia el mercado", "Hacia el viaje", "Hacia la riqueza"], "«Y apresuraos hacia un perdón de vuestro Señor y hacia un Jardín tan ancho como los cielos y la tierra, preparado para los piadosos»."),
"faith_131": ("¿Qué responsabilidad impone el Corán al creyente respecto de su familia?", ["Preservarlos, y a sí mismo, de un Fuego", "Enriquecerlos", "Enseñarles idiomas", "Llevarlos de viaje"], "«¡Creyentes! Preservaos a vosotros mismos y a vuestras familias de un Fuego cuyo combustible son los hombres y las piedras»."),
"faith_132": ("¿Cómo define la aleya 2:177 la verdadera piedad (al-birr)?", ["Creer en Allah, el Último Día, los ángeles, el Libro y los profetas, y dar de los bienes", "Volver el rostro al este o al oeste", "Solo ayunar", "Viajar"], "«La piedad no consiste en volver el rostro hacia el este o el oeste, sino en creer en Allah, en el Último Día, en los ángeles, en el Libro y en los profetas»."),
"faith_133": ("¿Quién verá las obras realizadas, según la sura At-Tawba?", ["Allah, Su Mensajero ﷺ y los creyentes", "Nadie", "Solo los ángeles", "Los reyes"], "«Y di: obrad, pues Allah verá vuestras obras, y también Su Mensajero y los creyentes»."),
"faith_134": ("¿Con qué afirmación termina la sura Al-Ijlas?", ["«Y no hay nadie que se Le iguale»", "«Él es el más grande»", "«Él está cerca»", "«Él es el primero»"], "«Y no hay nadie que se Le iguale»."),
"faith_135": ("¿Qué cuatro nombres reúne la sura Al-Hadid en una sola aleya?", ["El Primero, el Último, el Manifiesto y el Oculto", "El Rey, el Santo, la Paz, el Fiel", "El Creador, el Originador, el Formador, el Sabio", "El Viviente, el Sustentador, el Oyente, el Vidente"], "«Él es el Primero y el Último, el Manifiesto y el Oculto, y Él conoce todas las cosas»."),
"faith_136": ("¿Qué nombres enumera el final de la sura Al-Hashr después de «el Soberano»?", ["El Santo, la Paz, el que da seguridad, el Custodio", "El Creador, el Formador", "El Perdonador, el Misericordioso", "El Oyente, el Vidente"], "«Él es Allah, el Soberano, el Santo, la Paz, el que da seguridad, el Custodio, el Poderoso»."),
"faith_137": ("¿Cómo se llama la fórmula «No hay más dios que Allah, Muhammad es Su Mensajero»?", ["La shahada (el testimonio de fe)", "La basmala", "La takbira", "La tasmiya"], "La shahada es la primera palabra del islam y el primero de sus pilares."),
"faith_138": ("¿Cómo se llama la fórmula «Allahu akbar»?", ["El takbir", "El tahlil", "El tasbih", "El tahmid"], "El takbir es «Allahu akbar», el tasbih «subhan Allah», el tahmid «al-hamdu lillah» y el tahlil «la ilaha illa-llah»."),
"faith_139": ("¿Cómo se llama la fórmula «En el nombre de Allah, el Compasivo, el Misericordioso»?", ["La basmala", "La hamdala", "La hawqala", "El istiryá'"], "La basmala abre todas las suras menos una; la hawqala es «la hawla wa la quwwata illa billah»."),
"faith_140": ("¿Qué palabras enseña el Corán a decir cuando sobreviene una desgracia?", ["«Somos de Allah y a Él retornaremos»", "«¿Por qué yo?»", "«Ya pasará»", "«Es el destino de los hombres»"], "«Aquellos que, cuando les alcanza una desgracia, dicen: “Somos de Allah y a Él retornaremos”»."),
"faith_141": ("¿Qué ordena decir el Corán al anunciar que se hará algo mañana?", ["«Si Allah quiere» (in sha' Allah)", "«Está prometido»", "«Sin falta»", "«Lo juro»"], "«Y no digas nunca de algo: “Lo haré mañana”, sin añadir: “si Allah quiere”»."),
"faith_142": ("¿Qué conocimiento reserva el Corán solo a Allah, al final de la sura Luqman?", ["La Hora, la lluvia, lo que hay en los úteros, lo que se ganará mañana y dónde se morirá", "El número de las estrellas", "Los nombres de los reyes", "La cuenta de los días"], "«Allah tiene el conocimiento de la Hora, hace descender la lluvia y sabe lo que hay en los úteros. Nadie sabe lo que ganará mañana ni en qué tierra morirá»."),
"faith_143": ("¿Qué dice el Corán sobre el plazo fijado para cada comunidad?", ["Cuando llega, no se retrasa ni se adelanta una hora", "Es modificable", "Allah no lo conoce", "Depende de los reyes"], "«Cada comunidad tiene un plazo: cuando llega su plazo, no lo retrasan ni lo adelantan una hora»."),
"faith_144": ("¿Qué promete el Corán a quien obra el bien, varón o mujer, siendo creyente?", ["Una vida buena, y una recompensa según lo mejor de sus obras", "La riqueza", "El poder", "La fama"], "«A quien obre el bien, varón o mujer, siendo creyente, le haremos vivir una vida buena»."),
"faith_145": ("¿Qué distinción establece el Corán entre «islam» y «fe» en la sura Al-Huyurat?", ["Decir «nos hemos sometido» no es todavía que la fe entre en los corazones", "Son la misma palabra", "La fe siempre precede", "El islam es solo para los sabios"], "«Dicen los beduinos: “Creemos”. Di: “Aún no creéis; decid más bien: nos hemos sometido, pues la fe no ha entrado todavía en vuestros corazones”»."),
"faith_146": ("¿Qué regla enuncia la sura Al-Ma'ida sobre la vida de una sola persona?", ["Quien mata a una persona es como si matara a toda la humanidad; quien salva a una, como si la salvara toda", "Cada vida cuenta por una", "Solo cuentan los parientes", "Solo cuenta el número"], "«Quien mate a una persona sin que sea por otra o por corrupción en la tierra, será como si hubiera matado a toda la humanidad; y quien salve una vida, será como si hubiera salvado a toda la humanidad»."),
"faith_147": ("¿Por cuánto multiplica el Corán la recompensa de la buena acción?", ["Por diez", "Por dos", "Por cien", "No se multiplica"], "«Quien venga con una buena acción tendrá diez veces otro tanto; y quien venga con una mala solo será retribuido con su equivalente»."),
"faith_148": ("¿Cómo describe la sura Fatir la relación de los hombres con Allah?", ["Ellos son los pobres, y Allah es el Rico, el Digno de alabanza", "Son Sus socios", "Son independientes", "Son Sus acreedores"], "«¡Hombres! Vosotros sois los pobres, necesitados de Allah, y Allah es el Rico, el Digno de alabanza»."),
"faith_149": ("¿Qué cuatro cualidades salvan de la perdición, según la sura Al-'Asr?", ["La fe, las buenas obras, exhortarse a la verdad y a la paciencia", "La riqueza, la fuerza, la belleza, la astucia", "El silencio, el sueño, el retiro, el ayuno", "El viaje, el comercio, la escritura, la lectura"], "«¡Por el tiempo! El hombre está en perdición, salvo quienes creen, obran el bien, se exhortan a la verdad y se exhortan a la paciencia»."),
"faith_150": ("¿En qué declaran creer los creyentes, en la penúltima aleya de la sura Al-Baqara?", ["En Allah, Sus ángeles, Sus libros y Sus mensajeros", "En un solo libro", "En un solo ángel", "En sus antepasados"], "«El Mensajero cree en lo que le ha sido revelado por su Señor, y también los creyentes: todos creen en Allah, en Sus ángeles, en Sus libros y en Sus mensajeros»."),
}
